  const data = JSON.parse(response.getContentText());
  const parts = data.candidates?.[0]?.content?.parts || [];
  const result = parts.filter(p=>!p.thought).map(p=>p.text||'').join('');
  if (!result) throw new Error('No Gemini text returned');
  return result;
}

